/* ================================================= */
/* 整体风格：葱蓝色调 (初音未来蓝) - 最终修正版 */
/* ================================================= */
@import url('https://fonts.googleapis.com/css2?family=Russo+One&display=swap');

/* 全局字体和背景 */
body, * {
  font-family: 'Russo One', sans-serif !important;
  font-size: 14px !important;
  color: #333333 !important;
  text-shadow: none !important;
  border-radius: 0 !important;
  transition: all 0.1s ease-in-out !important;
  image-rendering: pixelated;
}

/* 评论区字体 */
.sticky.top-0.my-0.mx-3.border-\[1\.5px\] * {
  font-family: system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif !important;
  font-weight: normal !important;
}

body {
  background-color: #FFFFFF !important;
  background-image: none !important;
}

/* 移除扫描线 */
.group .bg-gray-100\/90::after,
.group .bg-gray-100\/90::before {
  content: none !important;
}

/* AI输出框 */
.group .bg-gray-100\/90 {
  border: 2px solid #39C5BB !important;
  box-shadow: 0 0 0 1px #2B9A92 !important;
  background-color: #FFFFFF !important;
}

/* 左侧边栏 */
div.duration-500.w-60.MuiBox-root {
  background-color: #E0FFFF !important;
  border-right: 3px solid #39C5BB !important;
  box-shadow: inset 0 0 5px rgba(0, 0, 0, 0.1) !important;
  position: relative;
  overflow: hidden;
  color: #333333 !important;
}

/* “用户输入”标签 */
div.duration-500.w-60.MuiBox-root::before {
  content: '用户输入' !important;
  position: absolute !important;
  top: -15px !important;
  left: 10px !important;
  background-color: #39C5BB !important;
  color: #FFFFFF !important;
  padding: 5px 15px !important;
  font-size: 10px !important;
  font-weight: bold !important;
  transform: rotate(-5deg) !important;
  border: 2px solid #2B9A92 !important;
  box-shadow: 2px 2px 0 #1D6B65 !important;
  z-index: 2;
}

/* 底部输入框 */
#ai-chat-input {
  background-color: #E0FFFF !important;
  border: 2px solid #39C5BB !important;
  box-shadow: 0 0 0 1px #2B9A92 !important;
  color: #333333 !important;
  border-radius: 0 !important;
}

/* 顶栏 */
.sticky.w-full.top-0.h-16 {
  /* 顶栏背景改为粉色，以统一风格 */
  background-color: #FF69B4 !important;
  background-size: 8px 8px !important;
  border-bottom: 3px solid #CD5B9B !important; /* 深粉色边框 */
  box-shadow: 0 3px 8px rgba(0, 0, 0, 0.2) !important;
}

/* ------------------------------------------------- */
/* 【顶部按钮美化】 (粉色风格) */
/* ------------------------------------------------- */

/* 顶部 'mod、流式、评论、回到底部' 等按钮 */
.flex.items-center.gap-2.pb-2 > button {
    background: #FFFFFF !important;
    color: #333333 !important;
    border: 2px solid #FF69B4 !important; /* 粉色边框 */
    border-radius: 4px !important;
    box-shadow: 3px 3px 0px #CD5B9B !important; /* 深粉色阴影 */
    font-weight: bold !important;
    text-transform: none !important;
    transition: all 0.1s ease-in-out !important;
    padding: 6px 16px !important;
}

/* 顶部按钮悬停效果 - “按下” */
.flex.items-center.gap-2.pb-2 > button:hover {
    background: #FFE0F4 !important; /* 模拟按下的淡粉色 */
    color: #333333 !important;
    transform: translate(3px, 3px) !important;
    box-shadow: 0px 0px 0px #CD5B9B !important;
}

/* ------------------------------------------------- */
/* 【底部按钮美化】 (尺寸缩小, 背景透明) */
/* ------------------------------------------------- */

/* AI输入框右侧的按钮 (发送、清空等) */
/* 匹配类名，需根据您的平台调整 */
#ai-chat-bottom-input button,
#ai-chat-bottom-input .MuiButtonBase-root {
    /* 核心修改：背景透明 */
    background: transparent !important; 

    /* 核心修改：文字颜色改为粉色，以在透明背景上显示 */
    color: #FF69B4 !important; 

    /* 边框和阴影保持粉色系 */
    border: 2px solid #CD5B9B !important; 
    border-radius: 4px !important;
    box-shadow: 2px 2px 0px #AB4B7F !important; /* 略微缩小阴影 */
    font-weight: bold !important;
    transition: all 0.1s ease-in-out !important;

    /* 进一步缩小按钮尺寸 */
    padding: 3px 10px !important; 
    min-width: 30px !important; 
    font-size: 12px !important; 
}

/* 输入框右侧按钮悬停效果 */
#ai-chat-bottom-input button:hover,
#ai-chat-bottom-input .MuiButtonBase-root:hover {
    /* 悬停时背景色变为浅粉色，保持与顶部按钮一致的按下反馈 */
    background: #FFE0F4 !important; 
    color: #333333 !important; /* 悬停时文字变为深色 */
    transform: translate(2px, 2px) !important; /* 对应缩小的阴影 */
    box-shadow: 0px 0px 0px #AB4B7F !important;
}


/* ------------------------------------------------- */
/* 【加载中状态】 (Tips效果 - 修正动画) */
/* ------------------------------------------------- */

/* 动画：上下跳动 */
@keyframes jumpyTip {
    0%, 100% { transform: translateY(0); }
    50% { transform: translateY(-5px); }
}

/* 动画：提示文字更换 (更新内容) */
@keyframes tips {
    0% { content: "文末出现未截断才算完全输出，如果没有请刷新回复"; }
    20% { content: "玩家使用Gemini的时候如果老是输出不完全请开非流式"; }
    40% { content: "记忆数设置到2或4可以有效减少消耗"; }
    60% { content: "你知道吗？打开非流可以有效避免异常积分消耗"; }
    80% { content: "本卡做了CLD4.5适配，但不妨碍我骂A社是傻逼"; }
    100% { content: "文末出现未截断才算完全输出，如果没有请刷新回复"; }
}

/* 隐藏原来的三个点（子元素） */
.style_dot-flashing__8L91Q {
    display: none !important;
}

/* 父容器美化和动画 */
.flex.items-center.justify-center.w-6.h-5 {
    /* 扩大容器以容纳文字 */
    width: auto !important;
    height: auto !important;
    padding: 5px 10px !important;

    /* 整体Tips美化 */
    background: #FF69B4 !important; /* 粉色背景 */
    border: 2px solid #CD5B9B !important; /* 深粉色边框 */
    box-shadow: 3px 3px 0px #AB4B7F !important;
    color: #FFFFFF !important; /* 白色文字 */
    border-radius: 4px !important;
    font-size: 12px !important;
    font-weight: bold !important;

    /* 应用上下跳动动画 */
    animation: jumpyTip 1s ease-in-out infinite alternate !important;
}

/* 使用 ::before 伪元素来显示文字，并应用更换动画 */
.flex.items-center.justify-center.w-6.h-5::before {
    /* 替换为游戏 Tips 文字 */
    content: "正在思考中..."; /* 默认显示文字 */

    /* 应用文字更换动画 (5个提示 x 4秒/提示 = 20秒一循环) */
    animation: tips 20s step-end infinite !important; 

    color: #FFFFFF !important;
    padding: 0 !important;
}

/* 主体 */
.translate-y-0 .p-3.overflow-y-auto {
  background: transparent !important;
}

/* ================================================================ */
/* 【details 改造 - 步骤1: 历史回复中的 details】 
/* 默认情况下，所有 details 都在气泡内部正常显示 
/* ================================================================ */

/* 匹配所有 AI 气泡内的 details 标签 (假设在 .markdown-body 内) */
.group .bg-gray-100\/90 .markdown-body > details {
  position: relative; /* 确保在文档流中 */
  width: auto;      /* 宽度自动 */
  z-index: 1;       /* 降低 z-index */
  background-color: #E0FFFF;
  border: 2px solid #39C5BB;
  margin-bottom: 8px; /* 保持间距 */
  margin-top: 15px; /* 增加一点上边距 */
  transition: all 0.3s ease-in-out;
  box-shadow: 0 2px 5px rgba(0, 0, 0, 0.1);
  overflow: hidden;
  border-radius: 4px !important; /* 统一圆角 */
}

/* 历史回复中的 summary (标题栏) */
.group .bg-gray-100\/90 .markdown-body > details > summary {
  padding: 12px 15px; /* 正常内边距 */
  font-weight: bold;
  color: #FFFFFF !important;
  cursor: pointer;
  list-style: none; /* 移除默认标记 */
  outline: none;
  transition: all 0.3s ease !important;

  /* 关键: 改为水平排版 */
  writing-mode: horizontal-tb;
  text-orientation: unset;

  background-color: #39C5BB !important;
  border: none !important; /* 移除原有的边框 */
  border-bottom: 2px solid #2B9A92 !important; /* 用底部边框分隔 */
  box-shadow: none !important; /* 移除阴影 */

  position: relative; /* 用于伪元素箭头 */
}

.group .bg-gray-100\/90 .markdown-body > details > summary::-webkit-details-marker {
  display: none; /* 隐藏默认箭头 */
}

/* 历史回复中的 summary 自定义箭头 */
.group .bg-gray-100\/90 .markdown-body > details > summary::before {
  content: '▶';
  display: inline-block;
  font-size: 0.8em;
  margin-right: 10px;
  transition: transform 0.2s ease;
  color: #FFFFFF; /* 确保箭头是白色 */
}

.group .bg-gray-100\/90 .markdown-body > details[open] > summary::before {
  transform: rotate(90deg);
}

.group .bg-gray-100\/90 .markdown-body > details > summary:hover {
  background-color: #2B9A92 !important;
  color: #FFFFFF !important;
}

/* 历史回复中打开的状态 (内容区) */
.group .bg-gray-100\/90 .markdown-body > details[open] {
  position: relative;
  top: auto;
  transform: none;
  width: auto;
  max-height: none; /* 移除最大高度限制 */
  border-right: 2px solid #39C5BB; /* 补上右边框 */
  box-shadow: 0 2px 5px rgba(0, 0, 0, 0.1);
  overflow-y: visible; /* 正常滚动 */
}

/* 历史回复中打开的 summary (标题栏) */
.group .bg-gray-100\/90 .markdown-body > details[open] > summary {
  position: relative; /* 移除 sticky 定位 */
  top: auto;
  width: auto;
  box-shadow: none; /* 移除展开时的阴影 */
}

/* 移除历史回复中的 '关闭' 文字 */
.group .bg-gray-100\/90 .markdown-body > details[open] > summary::after {
  content: '';
  float: none;
}

/* 历史回复的内容区 */
.group .bg-gray-100\/90 .markdown-body > details[open] > *:not(summary) {
  padding: 15px 20px;
  background: #FFFFFF; /* 内容区白色背景，区别于标题 */
}

/* 历史回复内容区文本 */
.group .bg-gray-100\/90 .markdown-body > details[open] p,
.group .bg-gray-100\/90 .markdown-body > details[open] li,
.group .bg-gray-100\/90 .markdown-body > details[open] h1 {
  font-size: 14px;
  color: #333333;
}


/* ================================================================ */
/* 【details 改造 - 步骤2: 最新回复中的 details】 
/* 仅最后一个 AI 气泡内的 details 应用 fixed 侧边栏样式 
/* (这里的样式基本来自你的原始CSS)
/* ================================================================ */

/* 关键选择器: 'div.chat-container > div.mx-auto > div:last-of-type'
  这用于定位最后一条消息，如果你的平台HTML结构不同，可能需要调整这里。
*/

/* 基础 - 侧边栏折叠状态 */
div.chat-container > div.mx-auto > div:last-of-type .group .bg-gray-100\/90 .markdown-body > details {
  /* 覆盖步骤1的样式，改回 fixed 定位 */
  position: fixed;
  right: 0;
  width: 35px;
  z-index: 999;
  background-color: #E0FFFF;
  border: 2px solid #39C5BB;
  border-right: none;
  margin-bottom: 8px;
  margin-top: 0; /* 移除上边距 */
  transition: all 0.3s ease-in-out;
  box-shadow: -3px 3px 8px rgba(0, 0, 0, 0.1);
  overflow: hidden;
  border-radius: 0 !important; /* 侧边栏不需要圆角 */
}

/* 侧边栏按钮的垂直定位 (来自你的原始CSS) */
div.chat-container > div.mx-auto > div:last-of-type .group .bg-gray-100\/90 .markdown-body > details:nth-of-type(1) { top: 70px; }
div.chat-container > div.mx-auto > div:last-of-type .group .bg-gray-100\/90 .markdown-body > details:nth-of-type(2) { top: 150px; }
div.chat-container > div.mx-auto > div:last-of-type .group .bg-gray-100\/90 .markdown-body > details:nth-of-type(3) { top: 230px; }
div.chat-container > div.mx-auto > div:last-of-type .group .bg-gray-100\/90 .markdown-body > details:nth-of-type(4) { top: 310px; }
div.chat-container > div.mx-auto > div:last-of-type .group .bg-gray-100\/90 .markdown-body > details:nth-of-type(5) { top: 390px; }
div.chat-container > div.mx-auto > div:last-of-type .group .bg-gray-100\/90 .markdown-body > details:nth-of-type(6) { top: 470px; }

/* 侧边栏 summary 样式 (垂直文字) */
div.chat-container > div.mx-auto > div:last-of-type .group .bg-gray-100\/90 .markdown-body > details > summary {
  padding: 12px 5px;
  font-weight: bold;
  color: #FFFFFF !important;
  cursor: pointer;
  list-style: none;
  outline: none;
  transition: all 0.3s ease !important;

  /* 关键: 覆盖为垂直排版 */
  writing-mode: vertical-rl;
  text-orientation: mixed;

  background-color: #39C5BB !important;
  border: 2px solid #2B9A92 !important;
  border-right: none !important;
  border-bottom: none !important; /* 覆盖步骤1的 border-bottom */
  box-shadow: -5px 0 10px rgba(0, 0, 0, 0.2) !important;

  position: relative; /* 确保 position 不是 sticky */
}

/* 隐藏箭头 */
div.chat-container > div.mx-auto > div:last-of-type .group .bg-gray-100\/90 .markdown-body > details > summary::before {
    content: none;
}

div.chat-container > div.mx-auto > div:last-of-type .group .bg-gray-100\/90 .markdown-body > details > summary::-webkit-details-marker {
  display: none;
}

div.chat-container > div.mx-auto > div:last-of-type .group .bg-gray-100\/90 .markdown-body > details > summary:hover {
  background-color: #2B9A92 !important;
  color: #FFFFFF !important;
}

/* 侧边栏打开状态 (大面板) */
div.chat-container > div.mx-auto > div:last-of-type .group .bg-gray-100\/90 .markdown-body > details[open] {
  position: fixed;
  right: 0;
  top: 50%;
  transform: translateY(-50%);
  width: 300px;
  max-height: 80vh;              
  background-color: #E0FFFF;
  border: 3px solid #39C5BB;
  border-right: none;
  box-shadow: -5px 0 20px rgba(0, 0, 0, 0.2);
  z-index: 1000;
  overflow-y: auto;
  overflow-x: hidden;
  padding: 0;
}

/* 确保打开时覆盖 :nth-of-type 的 top */
div.chat-container > div.mx-auto > div:last-of-type .group .bg-gray-100\/90 .markdown-body > details[open]:nth-of-type(1),
div.chat-container > div.mx-auto > div:last-of-type .group .bg-gray-100\/90 .markdown-body > details[open]:nth-of-type(2),
div.chat-container > div.mx-auto > div:last-of-type .group .bg-gray-100\/90 .markdown-body > details[open]:nth-of-type(3),
div.chat-container > div.mx-auto > div:last-of-type .group .bg-gray-100\/90 .markdown-body > details[open]:nth-of-type(4),
div.chat-container > div.mx-auto > div:last-of-type .group .bg-gray-100\/90 .markdown-body > details[open]:nth-of-type(5),
div.chat-container > div.mx-auto > div:last-of-type .group .bg-gray-100\/90 .markdown-body > details[open]:nth-of-type(6) {
  top: 50% !important; /* 使用 !important 确保覆盖 :nth-of-type */
}

/* 侧边栏打开时的 summary (顶部标题栏) */
div.chat-container > div.mx-auto > div:last-of-type .group .bg-gray-100\/90 .markdown-body > details[open] > summary {
  background-color: #39C5BB;
  color: #FFFFFF;
  padding: 12px 20px;
  border-bottom: 2px solid #2B9A92;
  width: 100%;              
  writing-mode: horizontal-tb;
  text-orientation: unset;
  position: sticky;  
  top: 0;
  left: 0;
  z-index: 2;
  box-shadow: 0 2px 5px rgba(0,0,0,0.1);
}

/* 侧边栏 "关闭" 文字 */
div.chat-container > div.mx-auto > div:last-of-type .group .bg-gray-100\/90 .markdown-body > details[open] > summary::after {
  content: '【点击此处关闭】';
  float: right;
  font-size: 0.8em;
  font-weight: normal;
  color: #FFFFFF;
}

/* 侧边栏内容区 */
div.chat-container > div.mx-auto > div:last-of-type .group .bg-gray-100\/90 .markdown-body > details[open] > *:not(summary) {
  padding: 15px 20px;
  background: transparent; /* 保持侧边栏底色 */
}

/* 侧边栏内的文本 */
div.chat-container > div.mx-auto > div:last-of-type .group .bg-gray-100\/90 .markdown-body > details[open] p,
div.chat-container > div.mx-auto > div:last-of-type .group .bg-gray-100\/90 .markdown-body > details[open] li,
div.chat-container > div.mx-auto > div:last-of-type .group .bg-gray-100\/90 .markdown-body > details[open] h1 {
  font-size: 14px;
  color: #333333;
}


