/* ================================================================ */

/* Python 代码框 (保持不变) */
.group pre {
  border: 2px solid #FF69B4 !important; /* 保持粉色 */
}

/* ---------------------------------------------------------------- */
/* 【Markdown ~内容~ 修正】 (保持不变) */
/* ---------------------------------------------------------------- */

* del, * s, .markdown-body del, .markdown-body s {
  text-decoration: none !important;
  color: inherit !important;
  font-size: inherit !important;
  font-weight: inherit !important;
  line-height: inherit !important;
  background-color: transparent !important;
  border: none !important;
  position: static !important;
}

* del::before, * s::before, .markdown-body del::before, .markdown-body s::before {
  content: '~' !important;
  color: inherit !important;
}

* del::after, * s::after, .markdown-body del::after, .markdown-body s::after {
  content: '~' !important;
  color: inherit !important;
}
